result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/glob2re.py", "content": """"glob2re.py -- compile glob patterns to regular expressions.

Supported syntax (on '/'-separated paths):
    *       matches any number of characters except '/'
    ?       matches exactly one character except '/'
    [seq]   character class (ranges allowed, e.g. [a-z])
    [!seq]  negated character class
    ]       as the first character of a class means a literal ']'
    **      as a complete path segment: any number of path segments
            (including zero), e.g. a/**/b matches a/b, a/x/b, a/x/y/b

Public API:
    compile(pattern) -> compiled regex (use .fullmatch)
    matches(pattern, path) -> bool
"""

import re

__all__ = ["compile", "matches"]


def _translate_class(body):
    """Escape the interior of a character class while keeping ranges intact."""
    out = []
    for k, ch in enumerate(body):
        if ch == "\\":
            out.append("\\\\")
        elif ch == "^" and k == 0:
            out.append("\\^")
        else:
            out.append(ch)
    return "".join(out)


def _translate_atom(pattern, i):
    """Translate one glob atom starting at index i.

    Returns (regex_fragment, next_index).
    """
    n = len(pattern)
    c = pattern[i]

    if c == "*":
        return "[^/]*", i + 1
    if c == "?":
        return "[^/]", i + 1
    if c == "[":
        j = i + 1
        negate = False
        if j < n and pattern[j] == "!":
            negate = True
            j += 1
        # ']' as the first character is a literal ']'
        if j < n and pattern[j] == "]":
            j += 1
        start = j
        while j < n and pattern[j] != "]":
            j += 1
        if j >= n:
            # Unclosed '[': treat as a literal bracket (like fnmatch)
            return re.escape("["), i + 1
        body = pattern[start:j]
        frag = "[" + ("^" if negate else "") + _translate_class(body) + "]"
        return frag, j + 1
    # Literal character (includes a lone '*'/'?'-free char, and '[' was handled)
    return re.escape(c), i + 1


def _translate_segment(segment):
    """Translate a single path segment (no '/' inside) to a regex fragment."""
    out = []
    i = 0
    n = len(segment)
    while i < n:
        frag, i = _translate_atom(segment, i)
        out.append(frag)
    return "".join(out)


def compile(pattern):
    """Compile a glob pattern into a regex suitable for re.fullmatch."""
    segments = pattern.split("/")
    pieces = []

    # Special case: the whole pattern is a lone '**'
    if len(segments) == 1 and segments[0] == "**":
        return re.compile(r".*")

    for idx, seg in enumerate(segments):
        first = idx == 0
        last = idx == len(segments) - 1
        sep = "" if first else "/"

        if seg == "**":
            if last:
                # 'a/**' -> 'a' optionally followed by /seg /seg ...
                pieces.append(r"(?:/[^/]+)*")
            else:
                # '**/rest' -> zero or more 'seg/' prefixes
                pieces.append(r"(?:[^/]+/)*")
        else:
            pieces.append(re.escape(sep) if sep else "")
            pieces.append(_translate_segment(seg))

    return re.compile("".join(pieces))


def matches(pattern, path):
    """Return True if the full path matches the glob pattern."""
    return compile(pattern).fullmatch(path) is not None
